<script lang="ts">
import { defineComponent, type PropType } from 'vue'; import type { ExploreEntry } from '../../api/explore';
export default defineComponent({name:'ExploreControls',props:{entries:{type:Array as PropType<ExploreEntry[]>,default:()=>[]},disabled:Boolean},emits:['update'],data(){return{drafts:{} as Record<string,string>}},watch:{entries:{immediate:true,deep:true,handler(entries:ExploreEntry[]){for(const entry of entries)if(entry.type==='text')this.drafts[entry.id]=entry.value||''}}},methods:{submit(entry:ExploreEntry){this.$emit('update',entry,this.drafts[entry.id]||'')}}});
</script>
<template><section v-if="entries.length" class="controls" :aria-label="$t('explore.controls.label')"><template v-for="entry in entries" :key="entry.id"><form v-if="entry.type==='text'" class="control text" @submit.prevent="submit(entry)"><label :for="`explore-${entry.id}`">{{ entry.title }}</label><div><input :id="`explore-${entry.id}`" v-model="drafts[entry.id]" :disabled="disabled"><button type="submit" :disabled="disabled">{{ $t('explore.controls.apply') }}</button></div></form><div v-else-if="entry.type==='button'" class="control"><span>{{ $t('explore.controls.action') }}</span><button type="button" :disabled="disabled" @click="$emit('update',entry,null)">{{ entry.title }}</button></div><label v-else-if="entry.type==='select'" class="control"><span>{{ entry.title }}</span><select :value="entry.value||''" :disabled="disabled" @change="$emit('update',entry,($event.target as HTMLSelectElement).value)"><option v-for="option in entry.options||[]" :key="option" :value="option">{{ option }}</option></select></label><fieldset v-else-if="entry.type==='toggle'" class="control" :disabled="disabled"><legend>{{ entry.title }}</legend><div class="toggles"><label v-for="option in entry.options||[]" :key="option"><input type="radio" :name="`explore-${entry.id}`" :value="option" :checked="entry.value===option" @change="$emit('update',entry,option)"><span>{{ option }}</span></label></div></fieldset></template></section></template>
<style scoped>.controls{display:grid;grid-template-columns:repeat(auto-fit,minmax(13rem,1fr));gap:.7rem}.control{min-width:0;margin:0;padding:.75rem;border:1px solid var(--color-border);border-radius:var(--radius-md);background:var(--color-paper-raised)}.control>span,.control>label,legend{display:block;margin-bottom:.4rem;color:var(--color-ink-muted);font-size:.78rem;font-weight:700}.text div{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:.45rem}input,select,button{min-height:2.75rem;border:1px solid var(--color-border);border-radius:var(--radius-sm);background:white;color:var(--color-ink);font:inherit}input,select{width:100%;padding:.55rem}button{padding:.55rem .8rem}.control:not(.text)>button{width:100%}.toggles{display:flex;flex-wrap:wrap;gap:.4rem}.toggles label{position:relative}.toggles input{position:absolute;opacity:0;pointer-events:none}.toggles span{min-height:2.75rem;display:flex;align-items:center;border:1px solid var(--color-border);border-radius:var(--radius-sm);padding:.55rem .75rem}.toggles input:checked+span{border-color:var(--color-accent);background:var(--color-accent);color:white}:disabled{opacity:.6}@media(max-width:30rem){.controls{grid-template-columns:1fr}.text div{grid-template-columns:1fr}}</style>